278	    private function ensureSidestUpdatesSubscription(?string $email): void
279	    {
280	        $email = is_string($email) ? strtolower(trim($email)) : '';
281	        if ($email === '') {
282	            return;
283	        }
284	
285	        $listKey = 'sidest_updates';
286	
287	        $existing = EmailSubscription::query()
288	            ->whereNull('professional_id')
289	            ->where('list_key', $listKey)
290	            ->where('email_lc', $email)
291	            ->first();
292	
293	        if ($existing) {
