346	
347	        $settings['brand_partner'] = $brandPartner;
348	        $settings['additional_brand_partners'] = $links
349	            ->filter(static fn ($link): bool => (int) $link->slot > BrandPartnerLinkService::PRIMARY_SLOT)
350	            ->sortBy('slot')
351	            ->map(static fn ($link): array => [
352	                'professional_id' => (string) $link->brand_professional_id,
353	            ])
354	            ->values()
355	            ->all();
